package com.cpf.starter.objectstorage;import java.net.URI;import org.springframework.boot.context.properties.ConfigurationProperties;@ConfigurationProperties("cpf.integration.object-storage") public class CpfObjectStorageProperties {private boolean enabled;private String bucket,region="ap-northeast-2",endpoint;private boolean pathStyle;private long maxBytes=5368709120L;public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getBucket(){return bucket;}public void setBucket(String v){bucket=v;}public String getRegion(){return region;}public void setRegion(String v){region=v;}public String getEndpoint(){return endpoint;}public void setEndpoint(String v){endpoint=v;}public boolean isPathStyle(){return pathStyle;}public void setPathStyle(boolean v){pathStyle=v;}public long getMaxBytes(){return maxBytes;}public void setMaxBytes(long v){maxBytes=v;}public void validate(){if(!enabled)return;if(bucket==null||bucket.isBlank()||region==null||maxBytes<1)throw new IllegalStateException("object-storage bucket/region/limit required");if(endpoint!=null)URI.create(endpoint);}}
